// Maps a schema-validated form onto an existing §18 decision action.
//
// Takes a body of the `application/json` content type, and returns a wrapper object for the known response body format(s).
//
// Corresponds with POST /api/v1/cycles/{id}/forms (the `SubmitForm` operationId).
func (c *ClientWithResponses) SubmitFormWithResponse(ctx context.Context, id CycleID, body SubmitFormJSONRequestBody, reqEditors ...RequestEditorFn) (*SubmitFormResponse, error) {
	rsp, err := c.SubmitForm(ctx, id, body, reqEditors...)
	if err != nil {
		return nil, err
	}
	return ParseSubmitFormResponse(rsp)
}

